// One stamp for the whole run, so every object this workflow makes is named
// zzz-test-<stamp>-... and can be told apart from anything else.
const stamp = new Date().toISOString().replace(/[-:T.Z]/g, '').slice(0, 14);
return [{ json: { stamp, prefix: 'zzz-test-' + stamp } }];

// Builds one item with one string field, "report", to copy in a single click.
//
// The rule this file exists to keep: a line may only say "ok" when the output it
// describes is actually there. A step that errored, produced no item, or came
// back without the field the step is supposed to produce, says FAIL. A step
// whose input never existed says SKIPPED. Nothing else may print "ok".

const W = 22;
const pad = (s) => (s + '                          ').slice(0, W);
const lines = [];
const failures = [];
const notes = [];

/** A value out of a nested object by dotted path, or undefined. */
function at(obj, path) {
  return String(path)
    .split('.')
    .reduce((o, k) => (o === undefined || o === null ? undefined : o[k]), obj);
}

function has(obj, path) {
  const v = at(obj, path);
  return !(v === undefined || v === null || v === '');
}

/** MISSING, never "?", so a hole in the data reads as a hole. */
const v = (x) => (x === undefined || x === null || x === '' ? 'MISSING' : String(x));

const oneLine = (s, n) => String(s).replace(/\s+/g, ' ').trim().slice(0, n || 200);

/**
 * n8n does not put a failed step's error in one place. A routing node that
 * continues on error yields { json: {}, error }, a programmatic node yields
 * { json: { error } }, a serialised NodeApiError is an object with message and
 * description, and the API's own refusal can arrive as a body. Look everywhere,
 * and take the first thing that reads like a sentence.
 */
function errorText(item) {
  const seen = [];
  const dig = (e, depth) => {
    if (e === undefined || e === null || depth > 4) return;
    if (typeof e === 'string') {
      if (e.trim()) seen.push(e.trim());
      return;
    }
    if (typeof e !== 'object') return;
    for (const k of ['message', 'description', 'reason', 'error', 'detail', 'errorMessage']) {
      dig(e[k], depth + 1);
    }
    if (e.httpCode) seen.push('HTTP ' + e.httpCode);
    if (!seen.length) {
      try {
        seen.push(JSON.stringify(e).slice(0, 200));
      } catch (err) {
        seen.push(String(e));
      }
    }
  };
  dig(item && item.error, 0);
  dig(item && item.json && item.json.error, 0);
  const j = (item && item.json) || {};
  if (!seen.length && j.success === false) dig(j.message || j.error || j, 0);
  const uniq = seen.filter((s, i) => seen.indexOf(s) === i);
  return uniq.length ? oneLine(uniq.join(' — '), 220) : null;
}

/** What one referenced node actually produced. Never throws. */
function outcome(node) {
  let items;
  try {
    items = $(node).all();
  } catch (e) {
    return { ran: false, json: {}, binary: {}, error: 'this step did not run (' + oneLine(e.message, 120) + ')' };
  }
  if (!items || !items.length) {
    return { ran: false, json: {}, binary: {}, error: 'this step produced no item at all' };
  }
  const item = items[0] || {};
  return {
    ran: true,
    json: item.json || {},
    binary: item.binary || {},
    error: errorText(item),
  };
}

/** Cache, so every step is judged once and the cleanup line agrees with the rows. */
const seenOutcome = {};
const out = (node) => (seenOutcome[node] = seenOutcome[node] || outcome(node));

const fileInfo = (b) => {
  const f = b && b.data;
  if (!f) return null;
  let bytes = null;
  try {
    if (f.data) bytes = Buffer.from(f.data, 'base64').length;
  } catch (e) {
    /* binary held outside the item: size unknown, the file is still there */
  }
  return (f.mimeType || 'unknown type') + ' ' + (bytes != null ? bytes + ' B' : f.fileSize || 'size unknown');
};

const results = {}; // label -> 'ok' | 'FAIL' | 'SKIPPED'

/**
 * One line of the report.
 *   skip     a sentence if this step could not mean anything, else null
 *   need     dotted paths in the JSON that MUST be there for the step to count
 *   binary   a binary field that MUST be there
 *   check    extra test; return a string to fail with it
 *   describe what to print when the step passed
 */
function step(label, node, opts) {
  const o = opts || {};
  if (o.skip) {
    results[label] = 'SKIPPED';
    lines.push(pad(label) + 'SKIPPED  ' + o.skip);
    return false;
  }
  const r = out(node);
  const reasons = [];
  if (r.error) reasons.push(r.error);
  for (const p of o.need || []) {
    if (!has(r.json, p)) reasons.push('no ' + p + ' in the output');
  }
  if (o.binary && !(r.binary && r.binary[o.binary])) {
    reasons.push('no binary field "' + o.binary + '" — no file came back');
  }
  if (!reasons.length && o.check) {
    let extra = null;
    try {
      extra = o.check(r.json, r.binary);
    } catch (e) {
      extra = 'could not be checked: ' + oneLine(e.message, 120);
    }
    if (extra) reasons.push(extra);
  }
  if (reasons.length) {
    const why = oneLine(reasons.join('; '), 240);
    results[label] = 'FAIL';
    failures.push(label + ' — ' + why);
    lines.push(pad(label) + 'FAIL     ' + why);
    return false;
  }
  let note = '';
  try {
    note = o.describe ? String(o.describe(r.json, r.binary) === undefined ? '' : o.describe(r.json, r.binary)) : '';
  } catch (e) {
    note = '(passed, but could not be summarised: ' + oneLine(e.message, 120) + ')';
  }
  results[label] = 'ok';
  lines.push(pad(label) + 'ok       ' + note);
  return true;
}

const ok = (label) => results[label] === 'ok';

// ---------------------------------------------------------------- the run

const prep = out('Prepare');
const stamp = prep.json.stamp || 'unknown';
const prefix = prep.json.prefix || 'zzz-test';

// 1. The credential, before anything that needs it. One cheap authenticated
//    call, answered whatever the status, so a 401 arrives as a 401 and not as
//    an empty item.
const cred = out('Check Credential');
const credBody = cred.json.body || {};
const credStatus = cred.json.statusCode;
let credProblem = null;
if (cred.error && credStatus === undefined) {
  credProblem = /credential/i.test(cred.error)
    ? 'credential not set or not found — ' + cred.error
    : cred.error;
} else if (credStatus === undefined) {
  credProblem = 'credential not working — the check produced no response at all';
} else if (credStatus === 401 || credStatus === 403) {
  credProblem =
    'credential not working — HTTP ' +
    credStatus +
    ' ' +
    oneLine(at(credBody, 'error.message') || at(credBody, 'message') || 'the key was refused', 120);
} else if (credStatus !== 200 || !has(credBody, 'data.workspace')) {
  credProblem =
    'credential not working — HTTP ' +
    v(credStatus) +
    ' ' +
    oneLine(at(credBody, 'error.message') || JSON.stringify(credBody).slice(0, 120), 140);
}

// A second opinion, so a credential that is set on the QRSalt nodes but not on
// the check node cannot make the whole report read SKIPPED. Get Many Folders is
// the cheapest authenticated call the node itself makes.
const probe = out('Get Many Folders');
const probeWorks = !probe.error && Array.isArray(probe.json.data);

if (credProblem && probeWorks) {
  results.credential = 'FAIL';
  failures.push(
    'credential — the QRSalt nodes authenticate fine, but the Check Credential node could not: ' + credProblem,
  );
  lines.push(
    pad('credential') +
      'FAIL     the QRSalt nodes authenticate, but this check could not (' +
      credProblem +
      '). Set the QRSalt API credential on the Check Credential node too.',
  );
} else if (credProblem) {
  results.credential = 'FAIL';
  failures.push('credential — ' + credProblem);
  lines.push(pad('credential') + 'FAIL     ' + credProblem);
} else {
  results.credential = 'ok';
  const plan = at(credBody, 'data.workspace.plan');
  lines.push(
    pad('credential') +
      'ok       workspace=' +
      v(at(credBody, 'data.workspace.name') || at(credBody, 'data.workspace.id')) +
      ' plan=' +
      v(plan),
  );
  if (plan === 'FREE' || plan === 'STARTER') {
    notes.push(
      'This key is on the ' +
        plan +
        ' plan, which does not include API access: only QR Image → Render can pass. Every other step below is expected to fail with the plan message, and that is the API refusing, not the node.',
    );
  }
}

const noCred = credProblem && !probeWorks ? 'credential not working, so this was not tried' : null;

// 2. The two operations that need no account at all. They are tested even when
//    the credential is broken, because they do not use it.
step('renderFree', 'Render (Free)', {
  binary: 'data',
  describe: (j, b) => fileInfo(b),
});

step('readFree', 'Read (Free)', {
  need: ['data'],
  check: (j) => {
    const keys = ['success', 'data', 'format'];
    const missing = keys.filter((k) => !(k in j));
    if (missing.length) return 'the answer is the wrong shape, missing: ' + missing.join(',');
    if (String(j.data).indexOf(prefix) === -1) {
      return 'decoded "' + oneLine(j.data, 60) + '", which is not the image Render (Free) just made';
    }
    return null;
  },
  describe: (j) => 'read back "' + oneLine(j.data, 48) + '" format=' + v(j.format),
});

// 3. Everything from here needs the key.
step('render', 'Render', { skip: noCred, binary: 'data', describe: (j, b) => fileInfo(b) });

step('codeCreate', 'Create QR Code', {
  skip: noCred,
  need: ['data.id', 'data.shortUrl'],
  describe: (j) =>
    'id=' + v(at(j, 'data.id')) + ' slug=' + v(at(j, 'data.slug')) + ' link=' + v(at(j, 'data.shortUrl')),
});
const madeA = ok('codeCreate');
const noA = noCred || (madeA ? null : 'QR code A was never created, so this could not be tried');

step('codeCreateB', 'Create QR Code B', {
  skip: noCred,
  need: ['data.id'],
  describe: (j) => 'id=' + v(at(j, 'data.id')),
});
const madeB = ok('codeCreateB');

step('scanFired', 'Fire a Scan', {
  skip: noA,
  need: ['statusCode'],
  check: (j) => {
    const s = Number(j.statusCode);
    if (s >= 200 && s < 400) return null;
    return 'HTTP ' + j.statusCode + ' from the short link — it did not redirect, so no scan was recorded';
  },
  describe: (j) => 'HTTP ' + j.statusCode + ' from the short link — a real scan',
});

step('codeGet', 'Get QR Code', {
  skip: noA,
  need: ['data.id'],
  describe: (j) => 'name=' + v(at(j, 'data.name')) + ' status=' + v(at(j, 'data.status')),
});

step('codeUpdate', 'Update QR Code', {
  skip: noA,
  need: ['data.destination'],
  check: (j) =>
    String(at(j, 'data.destination')).indexOf(prefix + '-a2') === -1
      ? 'destination came back as "' + oneLine(at(j, 'data.destination'), 60) + '", not the one that was set'
      : null,
  describe: (j) => 'destination=' + oneLine(at(j, 'data.destination'), 60),
});

step('codeGetImage', 'Get QR Image', { skip: noA, binary: 'data', describe: (j, b) => fileInfo(b) });

step('codeGetScans', 'Get Scans', {
  skip: noA,
  need: ['data.summary'],
  describe: (j) => v(at(j, 'data.summary.scans')) + ' scans, ' + v(at(j, 'data.summary.uniques')) + ' unique',
});

step('codeGetMany', 'Get Many QR Codes', {
  skip: noCred,
  need: ['data'],
  check: (j) => (Array.isArray(j.data) ? null : 'data is not a list'),
  describe: (j) => j.data.length + ' codes matching ' + prefix,
});

step('codeChangeMany', 'Change Many', {
  skip: noA,
  need: ['data.action'],
  describe: (j) =>
    'action=' +
    v(at(j, 'data.action')) +
    ' done=' +
    v(at(j, 'data.done')) +
    ' unchanged=' +
    v(at(j, 'data.unchanged')) +
    ' skipped=' +
    v(at(j, 'data.skipped')),
});

step('linkCreate', 'Create Short Link', {
  skip: noCred,
  need: ['data.id'],
  describe: (j) => 'id=' + v(at(j, 'data.id')) + ' link=' + v(at(j, 'data.shortUrl')),
});
const madeLink = ok('linkCreate');

step('linkGetMany', 'Get Many Short Links', {
  skip: noCred,
  need: ['data'],
  check: (j) => (Array.isArray(j.data) ? null : 'data is not a list'),
  describe: (j) => j.data.length + ' links matching ' + prefix,
});

step('analytics', 'Get Analytics', {
  skip: noCred,
  need: ['data.summary'],
  describe: (j) =>
    v(at(j, 'data.summary.scans')) +
    ' scans / ' +
    (Array.isArray(at(j, 'data.series')) ? at(j, 'data.series').length + ' days' : 'series MISSING') +
    ', ' +
    (Array.isArray(at(j, 'data.breakdown')) ? at(j, 'data.breakdown').length + ' breakdown rows' : 'breakdown MISSING'),
});

step('folderCreate', 'Create Folder', {
  skip: noCred,
  need: ['data.id'],
  describe: (j) => 'id=' + v(at(j, 'data.id')) + ' name=' + v(at(j, 'data.name')),
});
const madeFolder = ok('folderCreate');

const listStep = (label, node) =>
  step(label, node, {
    skip: noCred,
    need: ['data'],
    check: (j) => (Array.isArray(j.data) ? null : 'data is not a list'),
    describe: (j) => j.data.length + ' returned',
  });

listStep('folderGetMany', 'Get Many Folders');
listStep('tagGetMany', 'Get Many Tags');
listStep('utmGetMany', 'Get Many UTM Presets');
listStep('formGetMany', 'Get Many Forms');

const forms = out('Get Many Forms');
if (noCred) {
  results.formResponses = 'SKIPPED';
  lines.push(pad('formResponses') + 'SKIPPED  ' + noCred);
} else if (!Array.isArray(forms.json.data) || forms.json.data.length === 0) {
  results.formResponses = 'SKIPPED';
  lines.push(pad('formResponses') + 'SKIPPED  no QR Form exists in this workspace, so there is nothing to read');
} else {
  listStep('formResponses', 'Get Form Responses');
}

listStep('menuGetMany', 'Get Many QR Menus');

// 4. Cleanup. Every object this run made has to go again, and the line may only
//    say ok when each one that was made is gone.
step('codeDelete', 'Delete QR Code', {
  skip: madeA ? null : 'QR code A was never created, so there is nothing to delete',
  need: ['data'],
  describe: (j) => 'deleted, status now ' + v(at(j, 'data.status')),
});

step('codeBulkDelete', 'Bulk Delete QR Code B', {
  skip: madeB ? null : 'QR code B was never created, so there is nothing to delete',
  need: ['data.done'],
  check: (j) => (Number(at(j, 'data.done')) >= 1 ? null : 'the API reported done=' + v(at(j, 'data.done'))),
  describe: (j) => 'deleted, done=' + v(at(j, 'data.done')),
});

step('linkDelete', 'Delete Short Link', {
  skip: madeLink ? null : 'the short link was never created, so there is nothing to delete',
  need: ['data'],
  describe: (j) => 'deleted, status now ' + v(at(j, 'data.status')),
});

step('folderDelete', 'Delete Folder', {
  skip: madeFolder ? null : 'the folder was never created, so there is nothing to delete',
  need: ['data'],
  describe: (j) => 'deleted, ' + v(at(j, 'data.codesUnfiled')) + ' codes moved out of it (none deleted)',
});

if (results.linkDelete === 'FAIL') {
  notes.push(
    'The node has no Short Link → Delete operation, so this run deletes the short link through the QR code delete route with the link\'s ID. If that is refused, delete the link by hand in the dashboard.',
  );
}

const made = [
  ['QR code A', madeA, 'codeDelete'],
  ['QR code B', madeB, 'codeBulkDelete'],
  ['short link', madeLink, 'linkDelete'],
  ['folder', madeFolder, 'folderDelete'],
].filter((r) => r[1]);
const gone = made.filter((r) => ok(r[2]));
const leftBehind = made.filter((r) => !ok(r[2])).map((r) => r[0]);
if (!made.length) {
  lines.push(pad('cleanup') + 'ok       nothing was created, so there is nothing to clean up');
} else if (leftBehind.length) {
  failures.push('cleanup — still in the workspace: ' + leftBehind.join(', '));
  lines.push(
    pad('cleanup') +
      'FAIL     ' +
      gone.length +
      ' of ' +
      made.length +
      ' removed. Delete by hand: ' +
      leftBehind.join(', ') +
      ' (search for ' +
      prefix +
      ')',
  );
} else {
  lines.push(pad('cleanup') + 'ok       ' + gone.length + ' of ' + made.length + ' objects removed');
}

// 5. The verdict, first, so it cannot be missed.
notes.push('Scans are counted when QRSalt serves the redirect, so getScans may still read 0 if counting lags this run.');
if (noCred) {
  notes.push(
    'Fix the credential first: make a QRSalt API credential, open each QRSalt node and pick it, then run again. Nothing below the credential line was tested.',
  );
} else if (credProblem) {
  notes.push(
    'Only the Check Credential node is missing its credential. The rest of the run is real, but the workspace and plan could not be read.',
  );
}
const skipped = Object.keys(results).filter((k) => results[k] === 'SKIPPED');
if (skipped.length && !credProblem) {
  notes.push('SKIPPED means the step had no input to work on, not that it passed.');
}

const verdict = failures.length
  ? 'RESULT: FAILED — ' + failures.length + ' step' + (failures.length === 1 ? '' : 's') + ' did not work'
  : 'RESULT: PASSED — every step returned what it should';

const report = [
  verdict,
  'QRSalt n8n node test — ' + new Date().toISOString() + ' — run ' + stamp,
  ''.padEnd(72, '-'),
  ...lines,
  ''.padEnd(72, '-'),
  'FAILURES: ' + (failures.length ? failures.length : 'none'),
  ...failures.map((f) => '  - ' + f),
  'NOTES:',
  ...notes.map((t) => '  - ' + t),
].join('\n');

// "report" is the one field to copy; "passed" is there so another workflow can
// branch on it without parsing the text.
return [{ json: { report, passed: failures.length === 0 } }];
